def solve(n: int, L: int) -> QuantumCircuit:
    qc = QuantumCircuit(n)

    if L == 1 << n:
        qc.global_phase = pi
        return qc

    for bit in range(n - 1, -1, -1):
        if not (L & (1 << bit)):
            continue

        zero_qubits = [bit] + [
            q for q in range(bit + 1, n) if not (L & (1 << q))
        ]

        for q in zero_qubits:
            qc.x(q)

        controls = list(range(bit + 1, n))
        if controls:
            qc.h(bit)
            qc.mcx(controls, bit)
            qc.h(bit)
        else:
            qc.z(bit)

        for q in reversed(zero_qubits):
            qc.x(q)

    return qc

