def solve(n: int, L: int) -> QuantumCircuit:
    qc = QuantumCircuit(n)
    size = 1 << n
    qc.global_phase = pi * L / size

    for mask in range(1, size):
        coefficient = sum(
            1 if bin(state & mask).count("1") % 2 == 0 else -1
            for state in range(L)
        )
        if coefficient == 0:
            continue

        qubits = [q for q in range(n) if mask & (1 << q)]
        target = qubits[-1]
        controls = qubits[:-1]

        for control in controls:
            qc.cx(control, target)

        qc.rz(-2 * pi * coefficient / size, target)

        for control in reversed(controls):
            qc.cx(control, target)

    return qc

