def solve(n: int, L: int) -> QuantumCircuit:
    qc = QuantumCircuit(n)
    size = 1 << n

    coefficients = [int(state < L) for state in range(size)]
    for bit in range(n):
        for mask in range(size):
            if mask & (1 << bit):
                coefficients[mask] ^= coefficients[mask ^ (1 << bit)]

    if coefficients[0]:
        qc.global_phase = pi

    for mask in range(1, size):
        if not coefficients[mask]:
            continue

        qubits = [bit for bit in range(n) if mask & (1 << bit)]
        if len(qubits) == 1:
            qc.z(qubits[0])
        elif len(qubits) == 2:
            qc.cz(qubits[0], qubits[1])
        else:
            target = qubits[-1]
            qc.h(target)
            qc.mcx(qubits[:-1], target)
            qc.h(target)

    return qc

