def solve(n: int, L: int) -> QuantumCircuit:
    qc = QuantumCircuit(n)
    size = 1 << n

    if L <= size // 2:
        marked_states = range(L)
    else:
        qc.global_phase = pi
        marked_states = range(L, size)

    for state in marked_states:
        zero_bits = [q for q in range(n) if not ((state >> q) & 1)]

        for q in zero_bits:
            qc.x(q)

        if n == 1:
            qc.z(0)
        else:
            qc.mcp(pi, list(range(n - 1)), n - 1)

        for q in reversed(zero_bits):
            qc.x(q)

    qc = transpile(qc, basis_gates=["u", "cx"], optimization_level=1)
    return qc

