def solve(n: int, L: int) -> QuantumCircuit:
    qc = QuantumCircuit(n)

    if L == (1 << n):
        qc.global_phase = pi
        return qc

    for i in range(n - 1, -1, -1):
        if not (L & (1 << i)):
            continue

        controls = list(range(i + 1, n))
        flipped = [i] + [j for j in controls if not (L & (1 << j))]

        qc.x(flipped)
        if controls:
            qc.append(ZGate().control(len(controls)), controls + [i])
        else:
            qc.z(i)
        qc.x(flipped)

    return qc

