def solve(n: int, L: int) -> QuantumCircuit:
    qc = QuantumCircuit(n)

    if L == (1 << n):
        qc.global_phase = pi
        return qc

    flipped = [i for i in range(n) if not ((L >> i) & 1)]
    if flipped:
        qc.x(flipped)

    target = n - 1
    transitions = L ^ (L << 1)

    qc.h(target)
    for i in range(n):
        if (transitions >> i) & 1:
            controls = list(range(i, target))
            if controls:
                qc.mcx(controls, target)
            else:
                qc.x(target)
    qc.h(target)

    if flipped:
        qc.x(flipped)

    if (L >> target) & 1:
        qc.global_phase = pi

    return qc

