def solve(n: int, L: int) -> QuantumCircuit:
    qc = QuantumCircuit(n)
    size = 1 << n

    if L == size:
        qc.global_phase = pi
        return qc

    coefficients = [int(x < L) for x in range(size)]

    # Boolean Möbius transform.
    for bit in range(n):
        step = 1 << bit
        for base in range(0, size, step << 1):
            for offset in range(step):
                coefficients[base + step + offset] ^= coefficients[base + offset]

    best_coefficients = coefficients.copy()
    best_polarity = 0
    best_count = sum(coefficients[1:])
    previous_polarity = 0

    # Search fixed-polarity Reed-Muller representations in Gray-code order.
    for index in range(1, size):
        if best_count == 1:
            break

        polarity = index ^ (index >> 1)
        changed_bit = polarity ^ previous_polarity

        for base in range(0, size, changed_bit << 1):
            for offset in range(changed_bit):
                coefficients[base + offset] ^= coefficients[
                    base + changed_bit + offset
                ]

        count = sum(coefficients[1:])
        if count < best_count:
            best_count = count
            best_polarity = polarity
            best_coefficients = coefficients.copy()

        previous_polarity = polarity

    flipped = [q for q in range(n) if best_polarity & (1 << q)]
    for q in flipped:
        qc.x(q)

    if best_coefficients[0]:
        qc.global_phase = pi

    for monomial in range(1, size):
        if not best_coefficients[monomial]:
            continue

        qubits = [q for q in range(n) if monomial & (1 << q)]
        if len(qubits) == 1:
            qc.z(qubits[0])
        else:
            qc.mcp(pi, qubits[:-1], qubits[-1])

    for q in flipped:
        qc.x(q)

    return qc

