from qiskit.circuit.library import HGate, RYGate


def solve(n: int, L: int) -> QuantumCircuit:
    qc = QuantumCircuit(n)
    controls = []
    remaining = L

    while remaining > 1:
        width = (remaining - 1).bit_length()

        if remaining == (1 << width):
            for target in range(width):
                if controls:
                    qc.append(
                        HGate().control(len(controls)),
                        controls + [target],
                    )
                else:
                    qc.h(target)
            break

        target = width - 1
        left_size = 1 << target
        right_size = remaining - left_size
        theta = 2 * atan2(sqrt(right_size), sqrt(left_size))

        if controls:
            qc.append(
                RYGate(theta).control(len(controls)),
                controls + [target],
            )
        else:
            qc.ry(theta, target)

        left_controls = controls + [target]
        left_control_state = (1 << len(controls)) - 1

        for lower in range(target):
            qc.append(
                HGate().control(
                    len(left_controls),
                    ctrl_state=left_control_state,
                ),
                left_controls + [lower],
            )

        controls.append(target)
        remaining = right_size

    return qc

