def solve(n: int, L: int) -> QuantumCircuit:
    if not 1 <= n <= 10 or not 1 <= L <= (1 << n):
        raise ValueError("Require 1 <= n <= 10 and 1 <= L <= 2**n.")

    qc = QuantumCircuit(n)
    set_bits = [q for q in range(L.bit_length()) if (L >> q) & 1]

    remaining = L
    control = None

    for target in reversed(set_bits[1:]):
        block_size = 1 << target
        remaining -= block_size
        angle = 2.0 * atan2(sqrt(remaining), sqrt(block_size))

        if control is None:
            qc.ry(angle, target)
        else:
            qc.cry(angle, control, target)

        control = target

    for target in range(set_bits[0]):
        qc.h(target)

    for lower, upper in zip(set_bits, set_bits[1:]):
        qc.x(upper)
        for target in range(lower, upper):
            qc.ch(upper, target)
        qc.x(upper)

    return qc

