def solve(n: int, L: int) -> QuantumCircuit:
    qc = QuantumCircuit(n)

    if L == 1:
        return qc

    m = (L - 1).bit_length()
    size = 1 << m

    for q in range(m):
        qc.h(q)

    if L == size:
        return qc

    def qft(inverse: bool = False) -> None:
        # QFT without final swaps.
        if inverse:
            for target in range(m):
                for control in range(target):
                    qc.cp(
                        -pi / (1 << (target - control)),
                        control,
                        target,
                    )
                qc.h(target)
        else:
            for target in range(m - 1, -1, -1):
                qc.h(target)
                for control in range(target - 1, -1, -1):
                    qc.cp(
                        pi / (1 << (target - control)),
                        control,
                        target,
                    )

    def add_constant(offset: int) -> None:
        qft()
        for q in range(m):
            # Fourier weights are reversed because swaps were omitted.
            residue = (offset * (1 << (m - 1 - q))) % size
            if residue:
                qc.p(2.0 * pi * residue / size, q)
        qft(inverse=True)

    def phase_prefix(limit: int, angle: float) -> None:
        # Phase states x < limit by angle, up to a global phase.
        for q in range(m):
            qc.p(-angle * (1 << q) / size, q)

        add_constant(-limit)

        for q in range(m):
            qc.p(angle * (1 << q) / size, q)

        add_constant(limit)

    # One exact, phase-matched amplitude-amplification iteration.
    angle = acos(1.0 - size / (2.0 * L))
    phase_prefix(L, angle)

    for q in range(m):
        qc.h(q)

    phase_prefix(1, angle)

    for q in range(m):
        qc.h(q)

    return qc

import numpy as np
from qiskit import QuantumCircuit, transpile


def solve(n: int, L: int) -> QuantumCircuit:
    qc = QuantumCircuit(n)

    if L == 1:
        return qc

    m = (L - 1).bit_length()

    if L == (1 << m):
        qc.h(range(m))
        return qc

    def complete_unitary(columns):
        columns = np.asarray(columns, dtype=complex)
        dimension, count = columns.shape
        if count == dimension:
            return columns
        _, _, vh = np.linalg.svd(
            columns.conj().T, full_matrices=True
        )
        return np.column_stack(
            (columns, vh.conj().T[:, count:])
        )

    amplitudes = np.zeros(1 << m, dtype=complex)
    amplitudes[:L] = 1.0 / np.sqrt(L)
    remainder = amplitudes.reshape(1, -1)

    for q in range(m - 1):
        incoming = remainder.shape[0]
        half = remainder.shape[1] // 2

        matrix = (
            remainder.reshape(incoming, half, 2)
            .transpose(0, 2, 1)
            .reshape(2 * incoming, half)
        )

        u, singular_values, vh = np.linalg.svd(
            matrix, full_matrices=False
        )
        rank = int(np.count_nonzero(singular_values > 1e-12))

        tensor = (
            u[:, :rank] * singular_values[:rank]
        ).reshape(incoming, 2, rank)

        columns = np.zeros((4, incoming), dtype=complex)
        for old_bond in range(incoming):
            for bit in range(2):
                for new_bond in range(rank):
                    columns[bit + 2 * new_bond, old_bond] = (
                        tensor[old_bond, bit, new_bond]
                    )

        qc.unitary(complete_unitary(columns), [q, q + 1])
        remainder = vh[:rank, :]

    qc.unitary(complete_unitary(remainder.T), [m - 1])

    qc = transpile(
        qc,
        basis_gates=["u", "cx"],
        optimization_level=1,
    )
    return qc

from qiskit import QuantumCircuit
from qiskit.quantum_info import Clifford


def solve(n: int) -> QuantumCircuit:
    qc = QuantumCircuit(n)

    def pauli_label(positions, operator):
        label = ["I"] * n
        for qubit in positions:
            label[n - 1 - qubit] = operator
        return "".join(label)

    destabilizers = [pauli_label([0], "Z")]
    stabilizers = ["-" + "X" * n]

    for qubit in range(1, n):
        destabilizers.append(pauli_label([qubit], "X"))
        stabilizers.append(pauli_label([0, qubit], "Z"))

    preparation = Clifford.from_dict({
        "destabilizer": destabilizers,
        "stabilizer": stabilizers,
    })

    qc.compose(preparation.to_circuit(), inplace=True)
    return qc

