def solve(n: int, L: int, theta: float) -> QuantumCircuit:
    qc = QuantumCircuit(n)
    scale = theta / (1 << n)
    qc.global_phase = scale

    for target in range(n):
        previous_gray = 0

        for index in range(1 << target):
            gray = index ^ (index >> 1)
            changed = gray ^ previous_gray

            if changed:
                qc.cx(changed.bit_length() - 1, target)

            mask = (1 << target) | gray
            sign = -1 if bin(mask & L).count("1") % 2 else 1
            qc.rz(-2 * scale * sign, target)

            previous_gray = gray

        for control in range(target):
            if (previous_gray >> control) & 1:
                qc.cx(control, target)

    return qc

