def solve(n: int) -> QuantumCircuit:
    qc = QuantumCircuit(n)

    for layer in range(2 * n - 2, -1, -1):
        if layer % 2 == 0:
            qubit = layer // 2
            before = (pi / 2) * (1 - 2.0 ** (-(n - 1 - qubit)))
            after = (pi / 2) * (1 - 2.0 ** (-qubit))
            qc.u(pi / 2, after, pi + before, qubit)

        for high in range(min(n - 1, layer), layer // 2, -1):
            low = layer - high
            angle = -pi / (1 << (high - low + 1))
            qc.rzz(angle, low, high)

    for qubit in range(n // 2):
        qc.swap(qubit, n - 1 - qubit)

    qc.global_phase = -(pi / 4) * sum(
        (n - distance) / (1 << distance)
        for distance in range(1, n)
    )

    return qc

