def solve(n: int) -> QuantumCircuit:
    qc = QuantumCircuit(n)

    for target in range(n):
        qc.h(target)
        width = n - target

        if width > 1:
            diagonal = [1.0 + 0.0j] * (1 << width)
            for state in range(1, 1 << width, 2):
                angle = sum(
                    pi / (1 << distance)
                    for distance in range(1, width)
                    if state & (1 << distance)
                )
                diagonal[state] = exp(1j * angle)

            qc.append(DiagonalGate(diagonal), range(target, n))

    for qubit in range(n // 2):
        qc.swap(qubit, n - 1 - qubit)

    return qc

