from math import tau
from qiskit import QuantumCircuit


def solve(n: int, m: int, S: list[int]) -> QuantumCircuit:
    qc = QuantumCircuit(n)
    global_phase = 0.0

    # Binary-weight synthesis uses at most m single-qubit gate layers.
    for bit in range(m - 1, -1, -1):
        denominator_power = m - bit
        angle = tau / (1 << denominator_power)

        for qubit in range(n):
            if not ((S[qubit] >> bit) & 1):
                continue

            if denominator_power == 1:
                qc.z(qubit)
            elif denominator_power == 2:
                qc.s(qubit)
            elif denominator_power == 3:
                qc.t(qubit)
            else:
                qc.rz(angle, qubit)
                global_phase += angle / 2

    qc.global_phase = global_phase
    return qc

