    x, y = QuantumRegister(n), QuantumRegister(m)
    qc = QuantumCircuit(x, y)

    for j in range(m):
        qc.h(y[j])

    for i in range(n):
        for j in range(m):
            modulus = 1 << (j + 1)
            residue = S[i] % modulus
            if residue:
                qc.cp(2 * pi * residue / modulus, x[i], y[j])

    for j in range(m):
        for k in range(j):
            qc.cp(-pi / (1 << (j - k)), y[k], y[j])
        qc.h(y[j])

    return qc

