def solve(n: int, m: int, S: list[int]) -> QuantumCircuit:
    x, y = QuantumRegister(n), QuantumRegister(m)
    qc = QuantumCircuit(x, y)

    for i in range(n):
        value = S[i] % (1 << m)
        bit = 0

        while value and bit < m:
            if value & 1:
                digit = 1 if (value & 3) == 1 else -1

                if digit == 1:
                    targets = range(m - 1, bit - 1, -1)
                else:
                    targets = range(bit, m)

                for target in targets:
                    if target == bit:
                        qc.cx(x[i], y[target])
                    else:
                        controls = [x[i]] + [
                            y[j] for j in range(bit, target)
                        ]
                        qc.mcx(controls, y[target])

                value -= digit

            value >>= 1
            bit += 1

    return qc

