from qiskit.circuit.library import UCRYGate


def solve(n: int, m: int, S: list[int]) -> QuantumCircuit:
    x, y = QuantumRegister(n), QuantumRegister(m)
    qc = QuantumCircuit(x, y)

    size = 1 << n
    mask = (1 << m) - 1
    sums = [0] * size
    linear = [0] * size

    for value in range(1, size):
        bit = value & -value
        i = bit.bit_length() - 1
        previous = value ^ bit
        sums[value] = (sums[previous] + S[i]) & mask
        linear[value] = linear[previous] ^ S[i]

    residual = [a ^ b for a, b in zip(sums, linear)]
    groups = {}
    for j in range(m):
        truth = bytes((value >> j) & 1 for value in residual)
        if any(truth):
            groups.setdefault(truth, []).append(j)

    for truth, targets in groups.items():
        support = [
            i
            for i in range(n)
            if any(
                truth[value] != truth[value | (1 << i)]
                for value in range(size)
                if not (value & (1 << i))
            )
        ]

        reduced = []
        for assignment in range(1 << len(support)):
            value = sum(
                ((assignment >> k) & 1) << i
                for k, i in enumerate(support)
            )
            reduced.append(truth[value])

        pivot = y[targets[0]]
        controls = [x[i] for i in support]

        if reduced[-1] == 1 and sum(reduced) == 1:
            if len(controls) == 1:
                qc.cx(controls[0], pivot)
            else:
                qc.mcx(controls, pivot)
        else:
            qc.append(
                UCRYGate([pi * bit for bit in reduced]),
                [pivot] + controls,
            )

        for j in targets[1:]:
            qc.cx(pivot, y[j])

    for i in range(n):
        for j in range(m):
            if (S[i] >> j) & 1:
                qc.cx(x[i], y[j])

    return qc

