def solve(n: int, m: int, S: list[int]) -> QuantumCircuit:
    x, y = QuantumRegister(n), QuantumRegister(m)
    qc = QuantumCircuit(x, y)

    active = [i for i in range(n) if S[i]]
    if not active:
        return qc

    if len(active) == 1:
        i = active[0]
        for j in range(m):
            if (S[i] >> j) & 1:
                qc.cx(x[i], y[j])
        return qc

    denominator = 1 << m
    phase_units = [0] * (n + m)

    for i in active:
        for j in range(m):
            half = 1 << j
            residue = S[i] % (2 * half)

            if residue == 0:
                continue
            if residue == half:
                qc.cx(x[i], y[j])
                continue

            if residue > half:
                residue -= 2 * half

            qc.crx(pi * residue / half, x[i], y[j])
            phase_units[i] += residue * (1 << (m - j - 1))

    for j in range(1, m):
        for k in range(j):
            qc.crx(-pi / (1 << (j - k)), y[k], y[j])
            phase_units[n + k] -= 1 << (m - j + k - 1)

    for qubit, units in zip(list(x) + list(y), phase_units):
        units %= 2 * denominator
        if units > denominator:
            units -= 2 * denominator
        if units:
            qc.p(pi * units / denominator, qubit)

    return qc

