def solve(n: int, m: int, S: list[int]) -> QuantumCircuit:
    x, y = QuantumRegister(n), QuantumRegister(m)
    qc = QuantumCircuit(x, y)

    for j in range(m - 1, -1, -1):
        qc.h(y[j])
        for k in range(j - 1, -1, -1):
            qc.cp(pi / (1 << (j - k)), y[k], y[j])

    rounds = max(n, m)
    for shift in range(rounds):
        for i in range(n):
            j = (i + shift) % rounds
            if j < m:
                modulus = 1 << (j + 1)
                residue = S[i] % modulus
                if residue:
                    qc.cp(2 * pi * residue / modulus, x[i], y[j])

    for j in range(m):
        for k in range(j):
            qc.cp(-pi / (1 << (j - k)), y[k], y[j])
        qc.h(y[j])

    return qc

