def solve(n: int, m: int, S: list[int]) -> QuantumCircuit:
    x, y = QuantumRegister(n), QuantumRegister(m)
    qc = QuantumCircuit(x, y)

    for i, coefficient in enumerate(S):
        remaining = coefficient % (1 << m)
        bit = 0

        while remaining and bit < m:
            if remaining & 1:
                digit = 2 - (remaining & 3)
                remaining -= digit

                targets = (
                    range(m - 1, bit - 1, -1)
                    if digit == 1
                    else range(bit, m)
                )

                for target in targets:
                    if target == bit:
                        qc.cx(x[i], y[target])
                    else:
                        controls = [x[i]] + [y[j] for j in range(bit, target)]
                        qc.mcx(controls, y[target])

            remaining >>= 1
            bit += 1

    return qc

