from qiskit import QuantumCircuit, QuantumRegister


def solve(n: int, m: int, L: int, S: list[int], theta: float) -> QuantumCircuit:
    x, y = QuantumRegister(n), QuantumRegister(m)
    qc = QuantumCircuit(x, y)

    if theta == 0:
        return qc

    compute = QuantumCircuit(x, y)
    compute.h(y)

    width = max(n, m)
    for layer in range(width):
        for i in range(n):
            j = (i + layer) % width
            if j < m:
                modulus = 1 << (j + 1)
                residue = S[i] % modulus
                if residue:
                    compute.cp(
                        2 * pi * residue / modulus,
                        x[i],
                        y[j],
                    )

    for j in range(m):
        for k in range(j):
            compute.cp(-pi / (1 << (j - k)), y[k], y[j])
        compute.h(y[j])

    qc.compose(compute, inplace=True)

    zero_bits = [j for j in range(m) if ((L >> j) & 1) == 0]
    for j in zero_bits:
        qc.x(y[j])

    if m == 1:
        qc.p(theta, y[0])
    else:
        qc.mcp(theta, list(y[:-1]), y[-1])

    for j in zero_bits:
        qc.x(y[j])

    qc.compose(compute.inverse(), inplace=True)
    return qc

from qiskit import QuantumCircuit, QuantumRegister
from math import pi


def solve(n: int, m: int, L: int, S: list[int], theta: float) -> QuantumCircuit:
    x, y = QuantumRegister(n), QuantumRegister(m)
    qc = QuantumCircuit(x, y)

    if theta == 0:
        return qc

    def apply_phase_table(qubits, phases):
        size = len(phases)
        coefficients = phases[:]
        qc.global_phase += phases[0]

        stride = 1
        while stride < size:
            for start in range(0, size, 2 * stride):
                for offset in range(stride):
                    a = coefficients[start + offset]
                    b = coefficients[start + offset + stride]
                    coefficients[start + offset] = a + b
                    coefficients[start + offset + stride] = a - b
            stride *= 2

        scale = -2.0 / size
        for target in range(len(qubits)):
            count = 1 << target
            for step in range(count):
                gray = step ^ (step >> 1)
                angle = scale * coefficients[(1 << target) | gray]
                if angle != 0.0:
                    qc.p(angle, qubits[target])

                if target:
                    next_step = (step + 1) % count
                    next_gray = next_step ^ (next_step >> 1)
                    control = (gray ^ next_gray).bit_length() - 1
                    qc.cx(qubits[control], qubits[target])

    if n <= 5:
        modulus = 1 << m
        sums = [0] * (1 << n)
        phases = [0.0] * (1 << n)

        for state in range(1 << n):
            if state:
                bit = state & -state
                index = bit.bit_length() - 1
                sums[state] = (sums[state ^ bit] + S[index]) % modulus
            if sums[state] == L:
                phases[state] = theta

        apply_phase_table(list(x), phases)
        return qc

    angles = [
        [
            2.0 * pi * (S[i] % (1 << (j + 1))) / (1 << (j + 1))
            for j in range(m)
        ]
        for i in range(n)
    ]

    compute = QuantumCircuit(x, y)
    compute.h(y)

    for j in range(m):
        modulus = 1 << (j + 1)
        angle = (
            pi
            - 2.0 * pi * (L % modulus) / modulus
            + 0.5 * sum(angles[i][j] for i in range(n))
        )
        if angle != 0.0:
            compute.p(angle, y[j])

    for layer in range(n):
        for i in range(n):
            j = (i + layer) % n
            if j < m and angles[i][j] != 0.0:
                compute.cx(x[i], y[j])
                compute.p(-0.5 * angles[i][j], y[j])
                compute.cx(x[i], y[j])

    compute.h(y)
    qc.compose(compute, inplace=True)

    phases = [0.0] * (1 << m)
    phases[-1] = theta
    apply_phase_table(list(y), phases)

    qc.compose(compute.inverse(), inplace=True)
    return qc

from qiskit import QuantumCircuit, QuantumRegister


def solve(n: int, m: int, L: int, S: list[int], theta: float) -> QuantumCircuit:
    x, y = QuantumRegister(n), QuantumRegister(m)
    qc = QuantumCircuit(x, y)

    if theta == 0:
        return qc

    modulus = 1 << m
    active = [i for i in range(n) if S[i] % modulus]
    wires = [x[i] for i in active]

    if not active:
        if L == 0:
            qc.global_phase += theta
        return qc

    def parity_rotation(qubits, angle, phase_gate=False):
        pending = list(qubits)
        history = []
        while len(pending) > 1:
            following = []
            for i in range(0, len(pending) - 1, 2):
                a, b = pending[i], pending[i + 1]
                qc.cx(a, b)
                history.append((a, b))
                following.append(b)
            if len(pending) & 1:
                following.append(pending[-1])
            pending = following

        if phase_gate:
            qc.p(angle, pending[0])
        else:
            qc.rz(angle, pending[0])

        for a, b in reversed(history):
            qc.cx(a, b)

    if m == 1:
        if L == 0:
            qc.global_phase += theta
        parity_rotation(wires, theta if L else -theta, True)
        return qc

    width = len(wires)
    size = 1 << width
    residues = [0] * size
    spectrum = [0] * size
    spectrum[0] = int(L == 0)

    for state in range(1, size):
        bit = state & -state
        index = bit.bit_length() - 1
        residues[state] = (
            residues[state ^ bit] + S[active[index]]
        ) % modulus
        spectrum[state] = int(residues[state] == L)

    step = 1
    while step < size:
        for base in range(0, size, 2 * step):
            for offset in range(step):
                i, j = base + offset, base + offset + step
                a, b = spectrum[i], spectrum[j]
                spectrum[i], spectrum[j] = a + b, a - b
        step *= 2

    qc.global_phase += theta * spectrum[0] / size
    scale = -2.0 * theta / size

    def sweep(controls, targets, labels, table):
        count = len(controls)
        period = 1 << count
        low_mask = period - 1

        for t in range(period):
            gray = t ^ (t >> 1)

            for index, (target, label) in enumerate(zip(targets, labels)):
                if count:
                    shift = index % count
                    low = (
                        (gray << shift) | (gray >> (count - shift))
                    ) & low_mask
                else:
                    low = 0

                mask = (label << count) | low
                if mask and table[mask]:
                    qc.rz(scale * table[mask], target)

            if count:
                next_t = (t + 1) % period
                next_gray = next_t ^ (next_t >> 1)
                changed = (gray ^ next_gray).bit_length() - 1
                for index, target in enumerate(targets):
                    qc.cx(controls[(changed + index) % count], target)

    def small_diagonal(qubits, table):
        count = len(qubits)

        if count == 1:
            if table[1]:
                qc.rz(scale * table[1], qubits[0])
            return

        if count <= 6:
            a, b = qubits[-2:]
            qc.cx(a, y[0])
            qc.cx(b, y[0])

            sweep(
                qubits[:-2],
                [a, b, y[0], y[1]],
                [1, 2, 3, 0],
                table,
            )

            qc.cx(b, y[0])
            qc.cx(a, y[0])
            return

        controls = qubits[:4]
        a, b, c = qubits[4:]

        sweep(controls, [a, b, c, y[0]], [1, 2, 4, 0], table)

        changes = [
            (a, y[0]),
            (b, y[0]),
            (c, y[0]),
            (a, b),
            (a, c),
            (b, y[1]),
            (c, y[1]),
        ]
        for control, target in changes:
            qc.cx(control, target)

        sweep(controls, [b, c, y[0], y[1]], [3, 5, 7, 6], table)

        for control, target in reversed(changes):
            qc.cx(control, target)

    if width <= 7:
        small_diagonal(wires, spectrum)
        return qc

    support = [mask for mask in range(1, size) if spectrum[mask]]
    if not support:
        return qc

    directions = sorted(range(1, size), key=lambda a: (a.bit_count(), a))
    normal = None
    subspace = False

    for candidate in directions:
        if all((candidate & mask).bit_count() % 2 == 0 for mask in support):
            normal = candidate
            subspace = True
            break

    if normal is None:
        for candidate in directions:
            exceptions = 0
            for mask in support:
                if (candidate & mask).bit_count() % 2 == 0:
                    exceptions += 1
                    if exceptions > 1:
                        break
            if exceptions <= 1:
                normal = candidate
                break

    pivot = normal.bit_length() - 1
    remaining = [i for i in range(width) if i != pivot]
    order = remaining + [pivot]
    transformed_wires = [wires[i] for i in order]

    changes = []
    for i in remaining:
        if (normal >> i) & 1:
            qc.cx(wires[pivot], wires[i])
            changes.append((wires[pivot], wires[i]))

    transformed = [0] * size
    for mask, coefficient in enumerate(spectrum):
        new_mask = 0
        for j, original in enumerate(remaining):
            new_mask |= ((mask >> original) & 1) << j
        new_mask |= ((mask & normal).bit_count() & 1) << (width - 1)
        transformed[new_mask] = coefficient

    if subspace:
        small_diagonal(transformed_wires[:-1], transformed[:128])
    else:
        for mask in range(1, 128):
            if transformed[mask]:
                parity_rotation(
                    [
                        transformed_wires[i]
                        for i in range(7)
                        if (mask >> i) & 1
                    ],
                    scale * transformed[mask],
                )

        controls = transformed_wires[:4]
        targets = transformed_wires[4:]
        history = []

        def change(a, b):
            qc.cx(targets[a], targets[b])
            history.append((a, b))

        change(3, 0)
        change(3, 1)
        change(3, 2)
        sweep(controls, targets, [9, 10, 12, 8], transformed)

        for a, b in [(0, 1), (2, 3), (1, 2), (3, 0), (0, 1), (2, 3)]:
            change(a, b)

        sweep(controls, targets, [13, 14, 15, 11], transformed)

        for a, b in reversed(history):
            qc.cx(targets[a], targets[b])

    for control, target in reversed(changes):
        qc.cx(control, target)

    return qc

from qiskit import QuantumCircuit
from math import asin, sqrt


def solve(n: int) -> QuantumCircuit:
    qc = QuantumCircuit(n)
    qc.x(0)

    stride = 1
    while stride < n:
        pairs = []
        for source in range(stride):
            target = source + stride
            if target >= n:
                continue

            total = (n - 1 - source) // stride + 1
            retained = (n - 1 - source) // (2 * stride) + 1
            angle = asin(sqrt(retained / total))
            pairs.append((source, target, angle))

        for source, target, angle in pairs:
            qc.ry(angle, target)
        for source, target, angle in pairs:
            qc.cx(source, target)
        for source, target, angle in pairs:
            qc.ry(-angle, target)
        for source, target, angle in pairs:
            qc.cx(target, source)

        stride *= 2

    return qc

