from qiskit.circuit.library import XXPlusYYGate


def solve(n: int) -> QuantumCircuit:
    qc = QuantumCircuit(n)
    qc.x(0)

    for q in range(n - 1):
        theta = 2 * acos(1 / sqrt(n - q))
        qc.append(XXPlusYYGate(theta), [q, q + 1])

    for q in range(1, n):
        if q % 4:
            qc.p((q % 4) * pi / 2, q)

    return qc

