from qiskit import QuantumCircuit


def solve(n: int) -> QuantumCircuit:
    qc = QuantumCircuit(n)
    qc.x(0)

    intervals = [(0, n)]
    while intervals:
        rotations = []
        next_intervals = []

        for lower, upper in intervals:
            if upper - lower <= 1:
                continue

            middle = (lower + upper) // 2
            theta = 2 * asin(sqrt((upper - middle) / (upper - lower)))
            rotations.append((lower, middle, upper, theta))
            next_intervals.extend(((lower, middle), (middle, upper)))

        for lower, middle, upper, theta in rotations:
            if lower == 0:
                qc.ry(theta, middle)
            else:
                qc.cry(theta, lower, middle)

        for lower, middle, upper, theta in rotations:
            if upper < n:
                qc.cry(pi - theta, upper, middle)

        intervals = next_intervals

    prefix_operations = []
    stride = 1
    while stride < n:
        for target in range(2 * stride - 1, n, 2 * stride):
            prefix_operations.append((target - stride, target))
        stride *= 2

    stride //= 4
    while stride:
        for target in range(3 * stride - 1, n, 2 * stride):
            prefix_operations.append((target - stride, target))
        stride //= 2

    for control, target in reversed(prefix_operations):
        qc.cx(n - 1 - control, n - 1 - target)

    return qc

