from qiskit import QuantumCircuit


def solve(n: int) -> QuantumCircuit:
    qc = QuantumCircuit(n)

    qft = QuantumCircuit(n)
    for target in range(n - 1, -1, -1):
        qft.h(target)
        for control in range(target - 1, -1, -1):
            qft.cp(pi / (1 << (target - control)), control, target)

    for qubit in range(n // 2):
        qft.swap(qubit, n - 1 - qubit)

    inverse_qft = qft.inverse()

    def modular_shift(direction: int) -> None:
        qc.compose(qft, inplace=True)
        for qubit in range(n):
            qc.p(direction * 2 * pi / (1 << (n - qubit)), qubit)
        qc.compose(inverse_qft, inplace=True)

    modular_shift(-1)

    for qubit in range(n):
        qc.p(pi / (1 << (n - qubit)), qubit)

    modular_shift(1)

    for qubit in range(n):
        qc.p(-pi / (1 << (n - qubit)), qubit)

    qc.global_phase = pi + pi / (1 << n)

    return qc

