def solve(n: int, a: int) -> QuantumCircuit:
    k, c = QuantumRegister(n), QuantumRegister(1)
    qc = QuantumCircuit(k, c)

    a %= 1 << n
    if a == 0:
        return qc

    fourier = QuantumCircuit(n)
    for target in range(n - 1, -1, -1):
        fourier.h(target)
        for control in range(target - 1, -1, -1):
            fourier.cp(pi / (1 << (target - control)), control, target)

    for j in range(n // 2):
        fourier.swap(j, n - 1 - j)

    qc.compose(fourier, qubits=list(k), inplace=True)

    for bit in range(n):
        if (a >> bit) & 1:
            qc.cx(c[0], k[bit])
            for target in range(bit + 1, n):
                controls = [c[0]] + [k[j] for j in range(bit, target)]
                qc.mcx(controls, k[target])

    qc.compose(fourier.inverse(), qubits=list(k), inplace=True)

    return qc

