def solve(n: int, a: int) -> QuantumCircuit:
    k, c = QuantumRegister(n), QuantumRegister(1)
    qc = QuantumCircuit(k, c)

    # Update high bits first so each carry uses unchanged input bits.
    for target in range(n - 1, -1, -1):
        lower_constant = a & ((1 << target) - 1)
        constant_bit = (a >> target) & 1

        if lower_constant == 0:
            if constant_bit:
                qc.cx(c[0], k[target])
            continue

        threshold = (1 << target) - lower_constant
        lowest_one = (threshold & -threshold).bit_length() - 1

        qc.h(k[target])

        if constant_bit:
            qc.cp(pi, c[0], k[target])

        # Disjoint prefix conditions for the lower input being >= threshold.
        for pivot in range(lowest_one, target):
            if pivot != lowest_one and ((threshold >> pivot) & 1):
                continue

            negative_controls = [
                k[index]
                for index in range(pivot + 1, target)
                if ((threshold >> index) & 1) == 0
            ]
            controls = [c[0]] + [
                k[index] for index in range(pivot, target)
            ]

            for qubit in negative_controls:
                qc.x(qubit)

            qc.mcp(pi, controls, k[target])

            for qubit in reversed(negative_controls):
                qc.x(qubit)

        qc.h(k[target])

    return qc

