def solve(n: int, s: int, t: int) -> QuantumCircuit:
    qc = QuantumCircuit(n + 1)

    for target in range(n - 1, -1, -1):
        qc.h(target)
        for control in range(target - 1, -1, -1):
            qc.cp(pi / (1 << (target - control)), control, target)

    for target in range(n):
        modulus = 1 << (target + 1)
        shift = (-s) % modulus
        correction = (s - t) % modulus

        if shift:
            qc.p(2 * pi * shift / modulus, target)
        if correction:
            qc.cp(2 * pi * correction / modulus, n, target)

    for target in range(n):
        for control in range(target):
            qc.cp(-pi / (1 << (target - control)), control, target)
        qc.h(target)

    return qc

