def solve(n: int, s: int, t: int) -> QuantumCircuit:
    qc = QuantumCircuit(n + 1)

    def controlled_subtract(value: int) -> None:
        for bit in range(n):
            if value & (1 << bit):
                qc.cx(n, bit)
                for target in range(bit + 1, n):
                    controls = [n] + list(range(bit, target))
                    qc.mcx(controls, target)

    if s:
        qc.x(n)
        controlled_subtract(s)
        qc.x(n)

    controlled_subtract(t - (1 << n))

    return qc

from qiskit import QuantumCircuit


def solve(n: int, s: int, t: int) -> QuantumCircuit:
    qc = QuantumCircuit(n + 1)

    def synthesize_branch(value: int, branch: int) -> None:
        if value == 0:
            return

        if branch == 0:
            qc.x(n)

        # Synthesize output bits directly, preserving unprocessed lower bits.
        for target in range(n - 1, -1, -1):
            if (value >> target) & 1:
                qc.cx(n, target)

            # Disjoint predicates for lower_input < lower_constant.
            for pivot in range(target - 1, -1, -1):
                if not ((value >> pivot) & 1):
                    continue

                controls = [n] + list(range(pivot, target))
                zero_controls = [pivot] + [
                    bit
                    for bit in range(pivot + 1, target)
                    if not ((value >> bit) & 1)
                ]

                qc.x(zero_controls)
                qc.mcx(controls, target)
                qc.x(zero_controls)

        if branch == 0:
            qc.x(n)

    synthesize_branch(s, 0)
    synthesize_branch(t - (1 << n), 1)

    return qc

from qiskit import QuantumCircuit


def solve(n: int, s: int, t: int) -> QuantumCircuit:
    width = n + 1
    qc = QuantumCircuit(width)
    half = 1 << n
    size = 1 << width
    full_mask = size - 1

    permutation = [
        (k - s) % half if k < half else half + (k - t) % half
        for k in range(size)
    ]

    operations = []

    def emit(target, mask, value):
        while operations:
            previous_target, previous_mask, previous_value = operations[-1]
            if previous_target != target or previous_mask != mask:
                break

            difference = previous_value ^ value
            if difference == 0:
                operations.pop()
                return

            if difference & (difference - 1):
                break

            operations.pop()
            mask ^= difference
            value &= mask

        operations.append((target, mask, value))

    def exchange_states(a, b):
        path = []
        state = a
        difference = a ^ b

        while difference:
            bit_mask = difference & -difference
            target = bit_mask.bit_length() - 1
            mask = full_mask ^ bit_mask
            path.append((target, mask, state & mask))
            state ^= bit_mask
            difference ^= bit_mask

        for operation in path:
            emit(*operation)
        for operation in reversed(path[:-1]):
            emit(*operation)

    visited = bytearray(size)

    for start in range(size):
        if visited[start]:
            continue

        cycle = []
        current = start
        while not visited[current]:
            visited[current] = 1
            cycle.append(current)
            current = permutation[current]

        for index in range(len(cycle) - 2, -1, -1):
            exchange_states(cycle[index], cycle[index + 1])

    frame = 0

    for target, mask, value in operations:
        required_zeros = mask ^ value
        changes = (frame ^ required_zeros) & mask

        if changes:
            qc.x([bit for bit in range(width) if changes & (1 << bit)])
            frame ^= changes

        controls = [bit for bit in range(width) if mask & (1 << bit)]
        if not controls:
            qc.x(target)
        elif len(controls) == 1:
            qc.cx(controls[0], target)
        else:
            qc.mcx(controls, target)

    if frame:
        qc.x([bit for bit in range(width) if frame & (1 << bit)])

    return qc

from functools import lru_cache

from qiskit import QuantumCircuit


def solve(n: int, s: int, t: int) -> QuantumCircuit:
    width = n + 1
    half = 1 << n
    size = 1 << width
    qc = QuantumCircuit(width)

    permutation = [
        (k - s) % half
        if k < half
        else half + (k - t) % half
        for k in range(size)
    ]

    layer_count = 2 * width - 1
    switches = [bytearray(size // 2) for _ in range(layer_count)]

    def route(p, depth, prefix):
        length = len(p)

        if all(i == output for i, output in enumerate(p)):
            return

        if length == 2:
            switches[depth][prefix] = p[0]
            return

        block = length // 2
        mask = block - 1
        inverse = [0] * length
        for source, destination in enumerate(p):
            inverse[destination] = source

        colors = [-1] * length

        for start in range(length):
            if colors[start] != -1:
                continue

            colors[start] = 0
            stack = [start]

            while stack:
                source = stack.pop()
                opposite = 1 - colors[source]

                neighbors = (
                    source ^ block,
                    inverse[p[source] ^ block],
                )
                for neighbor in neighbors:
                    if colors[neighbor] == -1:
                        colors[neighbor] = opposite
                        stack.append(neighbor)

        offset = prefix * block
        switches[depth][offset:offset + block] = bytes(colors[:block])
        switches[layer_count - 1 - depth][offset:offset + block] = bytes(
            colors[inverse[destination]]
            for destination in range(block)
        )

        zero_branch = [0] * block
        one_branch = [0] * block

        for pair in range(block):
            source = pair + colors[pair] * block
            zero_branch[pair] = p[source] & mask
            one_branch[pair] = p[source ^ block] & mask

        route(zero_branch, depth + 1, prefix << 1)
        route(one_branch, depth + 1, (prefix << 1) | 1)

    route(permutation, 0, 0)

    @lru_cache(maxsize=None)
    def boolean_terms(table):
        ones = table.count(1)

        if ones == 0:
            return 0, ()
        if ones == len(table):
            return 1, ((0, 0),)

        bit = len(table) // 2
        low = table[:bit]
        high = table[bit:]

        if low == high:
            return boolean_terms(low)

        low_cost, low_terms = boolean_terms(low)
        high_cost, high_terms = boolean_terms(high)
        difference = bytes(a ^ b for a, b in zip(low, high))
        diff_cost, diff_terms = boolean_terms(difference)

        cost, _, mode = min(
            (
                low_cost + 2 * diff_cost,
                len(low_terms) + len(diff_terms),
                0,
            ),
            (
                high_cost + 2 * diff_cost,
                len(high_terms) + len(diff_terms),
                1,
            ),
            (
                2 * (low_cost + high_cost),
                len(low_terms) + len(high_terms),
                2,
            ),
        )

        if mode == 0:
            terms = low_terms + tuple(
                (mask | bit, value | bit)
                for mask, value in diff_terms
            )
        elif mode == 1:
            terms = high_terms + tuple(
                (mask | bit, value)
                for mask, value in diff_terms
            )
        else:
            terms = tuple(
                (mask | bit, value)
                for mask, value in low_terms
            ) + tuple(
                (mask | bit, value | bit)
                for mask, value in high_terms
            )

        return cost, terms

    for layer, table in enumerate(switches):
        depth = min(layer, layer_count - 1 - layer)
        target = width - 1 - depth
        variables = [qubit for qubit in range(width) if qubit != target]
        _, terms = boolean_terms(bytes(table))

        for mask, value in terms:
            controls = []
            negative_controls = []

            for position, qubit in enumerate(variables):
                bit = 1 << position
                if mask & bit:
                    controls.append(qubit)
                    if not value & bit:
                        negative_controls.append(qubit)

            if negative_controls:
                qc.x(negative_controls)

            if not controls:
                qc.x(target)
            elif len(controls) == 1:
                qc.cx(controls[0], target)
            else:
                qc.mcx(controls, target)

            if negative_controls:
                qc.x(negative_controls)

    boolean_terms.cache_clear()
    return qc

