from qiskit import QuantumCircuit


def solve(n: int, a: int, L: int) -> QuantumCircuit:
    qc = QuantumCircuit(n + 1)
    if a == 0:
        return qc

    width = (L - 1).bit_length()
    flag = n
    needs_reduction = L != (1 << width)

    def toggle_ge(threshold: int) -> None:
        boundary = threshold - 1
        for i in range(width):
            if (boundary >> i) & 1:
                continue

            negative_controls = [
                j for j in range(i + 1, width)
                if not ((boundary >> j) & 1)
            ]
            for j in negative_controls:
                qc.x(j)

            controls = list(range(i, width))
            if len(controls) == 1:
                qc.cx(controls[0], flag)
            else:
                qc.mcx(controls, flag)

            for j in reversed(negative_controls):
                qc.x(j)

    if needs_reduction:
        toggle_ge(L - a)

    for j in reversed(range(width)):
        qc.h(j)
        for k in reversed(range(j)):
            qc.cp(pi / (1 << (j - k)), k, j)

    for j in range(width):
        denominator = 1 << (j + 1)

        increment = a % denominator
        if increment:
            qc.p(2 * pi * increment / denominator, j)

        if needs_reduction:
            decrement = (-L) % denominator
            if decrement:
                qc.cp(2 * pi * decrement / denominator, flag, j)

    for j in range(width):
        for k in range(j):
            qc.cp(-pi / (1 << (j - k)), k, j)
        qc.h(j)

    if needs_reduction:
        toggle_ge(a)
        qc.x(flag)

    return qc

from qiskit import QuantumCircuit


def solve(n: int, a: int, L: int) -> QuantumCircuit:
    qc = QuantumCircuit(n + 1)
    if a == 0:
        return qc

    width = (L - 1).bit_length()
    size = 1 << width
    permutation = [
        (k + a) % L if k < L else k
        for k in range(size)
    ]
    inverse = [0] * size
    for index, value in enumerate(permutation):
        inverse[value] = index

    gates = []

    def apply_gate(control_mask: int, target_bit: int) -> None:
        gates.append((control_mask, target_bit.bit_length() - 1))
        free_mask = (size - 1) ^ (control_mask | target_bit)
        subset = free_mask

        while True:
            low = control_mask | subset
            high = low | target_bit
            left, right = inverse[low], inverse[high]

            permutation[left], permutation[right] = high, low
            inverse[low], inverse[high] = right, left

            if subset == 0:
                break
            subset = (subset - 1) & free_mask

    for expected in range(size):
        current = permutation[expected]
        missing = expected & ~current

        if missing:
            control_mask = current
            for bit in range(width):
                reduced = control_mask & ~(1 << bit)
                if reduced >= expected:
                    control_mask = reduced

            while missing:
                target_bit = missing & -missing
                apply_gate(control_mask, target_bit)
                missing ^= target_bit

        excess = permutation[expected] & ~expected
        while excess:
            target_bit = excess & -excess
            apply_gate(expected, target_bit)
            excess ^= target_bit

    for control_mask, target in reversed(gates):
        controls = [
            bit for bit in range(width)
            if control_mask & (1 << bit)
        ]
        if not controls:
            qc.x(target)
        elif len(controls) == 1:
            qc.cx(controls[0], target)
        elif len(controls) == 2:
            qc.ccx(controls[0], controls[1], target)
        elif len(controls) > 4:
            qc.mcx(
                controls,
                target,
                ancilla_qubits=[n],
                mode="recursion",
            )
        else:
            qc.mcx(controls, target)

    return qc

from qiskit import QuantumCircuit


def solve(n: int, a: int, L: int) -> QuantumCircuit:
    qc = QuantumCircuit(n + 1)
    if a == 0:
        return qc

    width = (L - 1).bit_length()
    data = list(range(width))
    flag = n

    def add_constant(qubits, value, control=None):
        size = len(qubits)
        subtract = value < 0
        amount = abs(value) % (1 << size)
        bit_order = range(size - 1, -1, -1) if subtract else range(size)

        for bit in bit_order:
            if not ((amount >> bit) & 1):
                continue

            targets = (
                range(bit, size)
                if subtract
                else range(size - 1, bit - 1, -1)
            )

            for index in targets:
                controls = qubits[bit:index]
                if control is not None:
                    controls = [control] + controls

                target = qubits[index]
                if not controls:
                    qc.x(target)
                elif len(controls) == 1:
                    qc.cx(controls[0], target)
                elif len(controls) == 2:
                    qc.ccx(controls[0], controls[1], target)
                else:
                    qc.mcx(controls, target)

    if L == (1 << width):
        add_constant(data, a)
        return qc

    extended = data + [flag]

    add_constant(extended, a - L)
    add_constant(data, L, control=flag)
    add_constant(extended, -a)
    qc.x(flag)
    add_constant(data, a)

    return qc

