from qiskit import QuantumCircuit


def solve(n: int, a: int, L: int) -> QuantumCircuit:
    qc = QuantumCircuit(n + 1)
    if a == 0:
        return qc

    width = (L - 1).bit_length()
    flag = n

    def controlled_x(controls, target):
        if not controls:
            qc.x(target)
        elif len(controls) == 1:
            qc.cx(controls[0], target)
        elif len(controls) == 2:
            qc.ccx(controls[0], controls[1], target)
        else:
            qc.mcx(controls, target)

    def toggle_prefix_membership(length):
        prefix = 0
        for bit in range(width - 1, -1, -1):
            if not (length & (1 << bit)):
                continue

            controls = list(range(bit, width))
            negative = [
                qubit for qubit in controls
                if not (prefix & (1 << qubit))
            ]

            for qubit in negative:
                qc.x(qubit)
            controlled_x(controls, flag)
            for qubit in reversed(negative):
                qc.x(qubit)

            prefix += 1 << bit

    def controlled_add(length, value):
        for target in range(length - 1, -1, -1):
            qc.h(target)
            for control in range(target - 1, -1, -1):
                qc.cp(
                    pi / (1 << (target - control)),
                    control,
                    target,
                )

        for target in range(length):
            modulus = 1 << (target + 1)
            residue = value % modulus
            if residue:
                qc.cp(2 * pi * residue / modulus, flag, target)

        for target in range(length):
            for control in range(target):
                qc.cp(
                    -pi / (1 << (target - control)),
                    control,
                    target,
                )
            qc.h(target)

    def reverse_prefix(length):
        if length <= 1:
            return

        bits = (length - 1).bit_length()

        if length == (1 << bits):
            controls = list(range(bits, width))
            for qubit in controls:
                qc.x(qubit)
            for target in range(bits):
                controlled_x(controls, target)
            for qubit in reversed(controls):
                qc.x(qubit)
            return

        toggle_prefix_membership(length)

        for target in range(bits):
            qc.cx(flag, target)
        controlled_add(bits, length)

        toggle_prefix_membership(length)

    reverse_prefix(L - a)
    reverse_prefix(L)
    reverse_prefix(a)

    return qc

