from qiskit import QuantumCircuit


def solve(n: int, a: int, L: int) -> QuantumCircuit:
    qc = QuantumCircuit(n + 1)
    if a == 0:
        return qc

    width = (L - 1).bit_length()
    size = 1 << width
    layers = [[0] * (size // 2) for _ in range(2 * width - 1)]

    def route(permutation, depth, prefix):
        length = len(permutation)
        if all(x == y for x, y in enumerate(permutation)):
            return

        if length == 2:
            layers[depth][prefix] = 1
            return

        inverse = [0] * length
        for x, y in enumerate(permutation):
            inverse[y] = x

        colors = [-1] * length
        for start in range(length):
            if colors[start] != -1:
                continue

            colors[start] = 0
            stack = [start]
            while stack:
                x = stack.pop()
                opposite = colors[x] ^ 1
                for neighbor in (x ^ 1, inverse[permutation[x] ^ 1]):
                    if colors[neighbor] == -1:
                        colors[neighbor] = opposite
                        stack.append(neighbor)

        first = layers[depth]
        last = layers[2 * width - 2 - depth]
        subpermutations = [[0] * (length // 2) for _ in range(2)]

        for pair in range(length // 2):
            first[prefix | (pair << depth)] = colors[2 * pair]

        for x, y in enumerate(permutation):
            channel = colors[x]
            subpermutations[channel][x >> 1] = y >> 1
            last[prefix | ((y >> 1) << depth)] = (y & 1) ^ channel

        route(subpermutations[0], depth + 1, prefix)
        route(subpermutations[1], depth + 1, prefix | (1 << depth))

    permutation = [
        (k + a) % L if k < L else k
        for k in range(size)
    ]
    route(permutation, 0, 0)

    def uniformly_controlled_rz(controls, target, angles):
        coefficients = list(angles)
        count = len(coefficients)

        step = 1
        while step < count:
            for base in range(0, count, 2 * step):
                for offset in range(step):
                    left = base + offset
                    right = left + step
                    u, v = coefficients[left], coefficients[right]
                    coefficients[left] = u + v
                    coefficients[right] = u - v
            step *= 2

        previous = 0
        for index in range(count):
            gray = index ^ (index >> 1)
            angle = coefficients[gray] / count
            if abs(angle) < 1e-14:
                continue

            difference = previous ^ gray
            while difference:
                bit = difference & -difference
                qc.cx(controls[bit.bit_length() - 1], target)
                difference ^= bit

            qc.rz(angle, target)
            previous = gray

        while previous:
            bit = previous & -previous
            qc.cx(controls[bit.bit_length() - 1], target)
            previous ^= bit

    def apply_diagonal(qubits, phases):
        qubits = list(qubits)
        phases = list(phases)

        while qubits:
            half = len(phases) // 2
            angles = [
                phases[index + half] - phases[index]
                for index in range(half)
            ]
            averages = [
                (phases[index + half] + phases[index]) / 2
                for index in range(half)
            ]

            uniformly_controlled_rz(
                qubits[:-1], qubits[-1], angles
            )
            qubits.pop()
            phases = averages

        qc.global_phase += phases[0]

    for layer_index, table in enumerate(layers):
        if not any(table):
            continue

        target = (
            layer_index
            if layer_index < width
            else 2 * width - 2 - layer_index
        )

        if all(table):
            qc.x(target)
            continue

        other_qubits = [q for q in range(width) if q != target]
        support = []

        for bit in range(width - 1):
            stride = 1 << bit
            dependent = any(
                table[base + offset] != table[base + offset + stride]
                for base in range(0, len(table), 2 * stride)
                for offset in range(stride)
            )
            if dependent:
                support.append(bit)

        indices = [0]
        for bit in support:
            indices += [index | (1 << bit) for index in indices]

        values = [table[index] for index in indices]
        controls = [other_qubits[bit] for bit in support]

        if len(controls) == 1:
            if values[0]:
                qc.x(target)
            qc.cx(controls[0], target)
            continue

        qc.h(target)
        apply_diagonal(
            controls + [target],
            [0.0] * len(values) + [pi * value for value in values],
        )
        qc.h(target)

    return qc

def solve(a: int, L: int) -> int:
    result: int = 0
    u, v = a, L
    x_u, y_u = 1, 0
    x_v, y_v = 0, 1

    while u:
        while (u & 1) == 0:
            u >>= 1
            if (x_u & 1) == 0 and (y_u & 1) == 0:
                x_u >>= 1
                y_u >>= 1
            else:
                x_u = (x_u + L) >> 1
                y_u = (y_u - a) >> 1

        while (v & 1) == 0:
            v >>= 1
            if (x_v & 1) == 0 and (y_v & 1) == 0:
                x_v >>= 1
                y_v >>= 1
            else:
                x_v = (x_v + L) >> 1
                y_v = (y_v - a) >> 1

        if u >= v:
            u -= v
            x_u -= x_v
            y_u -= y_v
        else:
            v -= u
            x_v -= x_u
            y_v -= y_u

    result = x_v % L
    return result

