def solve(n: int, a: int, L: int) -> QuantumCircuit:
    x, y = QuantumRegister(n), QuantumRegister(n + 1)
    qc = QuantumCircuit(x, y)

    def controlled_swap_states(control, first, second):
        edges = []
        state = first
        difference = first ^ second

        while difference:
            mask = difference & -difference
            bit = mask.bit_length() - 1
            edges.append((state, bit))
            state ^= mask
            difference ^= mask

        for state, bit in edges + edges[-2::-1]:
            zeros = [
                y[j]
                for j in range(n)
                if j != bit and ((state >> j) & 1) == 0
            ]
            controls = [control] + [y[j] for j in range(n) if j != bit]

            for qubit in zeros:
                qc.x(qubit)
            qc.mcx(controls, y[bit])
            for qubit in zeros:
                qc.x(qubit)

    for i in range(n):
        shift = (a * (1 << i)) % L
        if shift == 0:
            continue

        visited = [False] * L
        for start in range(L):
            if visited[start]:
                continue

            cycle = []
            current = start
            while not visited[current]:
                visited[current] = True
                cycle.append(current)
                current = (current + shift) % L

            for state in cycle[1:]:
                controlled_swap_states(x[i], cycle[0], state)

    return qc

