def solve(n: int, a: int, L: int) -> QuantumCircuit:
    x, y = QuantumRegister(n), QuantumRegister(n + 1)
    qc = QuantumCircuit(x, y)

    if a == 0 or L == 1:
        return qc

    def controlled_add(control, targets, constant):
        width = len(targets)
        modulus = 1 << width
        positive = constant % modulus
        if positive == 0:
            return

        negative = modulus - positive
        positive_cost = sum(
            width - k for k in range(width) if (positive >> k) & 1
        )
        negative_cost = sum(
            width - k for k in range(width) if (negative >> k) & 1
        )

        subtract = negative_cost < positive_cost
        magnitude = negative if subtract else positive

        for k in range(width):
            if not ((magnitude >> k) & 1):
                continue

            positions = (
                range(k, width)
                if subtract
                else range(width - 1, k - 1, -1)
            )
            for j in positions:
                controls = [control] + targets[k:j]
                if len(controls) == 1:
                    qc.cx(control, targets[j])
                else:
                    qc.mcx(controls, targets[j])

    def clear_flag(control, threshold):
        qc.cx(control, y[n])

        for k in range(n):
            if not ((threshold >> k) & 1):
                continue

            zeros = [y[k]] + [
                y[j]
                for j in range(k + 1, n)
                if not ((threshold >> j) & 1)
            ]

            for qubit in zeros:
                qc.x(qubit)

            qc.mcx([control] + list(y[k:n]), y[n])

            for qubit in reversed(zeros):
                qc.x(qubit)

    lower = list(y[:n])
    extended = list(y)

    for i in range(n):
        shift = (a * (1 << i)) % L
        if shift == 0:
            continue

        if L == (1 << n):
            controlled_add(x[i], lower, shift)
        else:
            controlled_add(x[i], extended, shift - L)
            controlled_add(y[n], lower, L)
            clear_flag(x[i], shift)

    return qc

