def solve(n: int, a: int, L: int) -> QuantumCircuit:
    x, y = QuantumRegister(n), QuantumRegister(n + 1)
    qc = QuantumCircuit(x, y)

    if a == 0 or L == 1:
        return qc

    def switch(enable, target, conditions):
        controls = [enable]
        negative_controls = []

        for bit, value in conditions:
            controls.append(y[bit])
            if value == 0:
                negative_controls.append(y[bit])

        for qubit in negative_controls:
            qc.x(qubit)

        if len(controls) == 1:
            qc.cx(controls[0], y[target])
        else:
            qc.mcx(controls, y[target])

        for qubit in reversed(negative_controls):
            qc.x(qubit)

    def route(permutation, bits, fixed, enable):
        size = len(permutation)
        if all(source == target for source, target in enumerate(permutation)):
            return

        if len(bits) == 1:
            switch(enable, bits[0], fixed)
            return

        half = size // 2
        mask = half - 1
        target_bit = bits[-1]
        remaining_bits = bits[:-1]

        inverse = [0] * size
        for source, target in enumerate(permutation):
            inverse[target] = source

        colors = [-1] * size
        for start in range(size):
            if colors[start] != -1:
                continue

            colors[start] = 0
            stack = [start]

            while stack:
                edge = stack.pop()
                opposite = 1 - colors[edge]
                neighbors = (
                    edge ^ half,
                    inverse[permutation[edge] ^ half],
                )

                for neighbor in neighbors:
                    if colors[neighbor] == -1:
                        colors[neighbor] = opposite
                        stack.append(neighbor)

        def switch_conditions(value):
            return fixed + [
                (bit, (value >> position) & 1)
                for position, bit in enumerate(remaining_bits)
            ]

        for pair in range(half):
            if colors[pair] == 1:
                switch(enable, target_bit, switch_conditions(pair))

        subnetworks = [[0] * half for _ in range(2)]
        for source, target in enumerate(permutation):
            subnetworks[colors[source]][source & mask] = target & mask

        for color in range(2):
            route(
                subnetworks[color],
                remaining_bits,
                fixed + [(target_bit, color)],
                enable,
            )

        for pair in range(half):
            if colors[inverse[pair]] == 1:
                switch(enable, target_bit, switch_conditions(pair))

    dimension = 1 << n
    for bit in range(n):
        shift = (a << bit) % L
        if shift == 0:
            continue

        permutation = [
            (value + shift) % L if value < L else value
            for value in range(dimension)
        ]
        route(permutation, list(range(n)), [], x[bit])

    return qc

