def solve(n: int, a: int, L: int) -> QuantumCircuit:
    x, y = QuantumRegister(n), QuantumRegister(n + 1)
    qc = QuantumCircuit(x, y)

    def swap_basis_states(left: int, right: int) -> None:
        edges = []
        state = left
        difference = left ^ right

        for target in range(n):
            if (difference >> target) & 1:
                edges.append((state, target))
                state ^= 1 << target

        for state, target in edges + list(reversed(edges[:-1])):
            controls = [x[i] for i in range(n) if i != target]
            open_controls = [
                x[i]
                for i in range(n)
                if i != target and ((state >> i) & 1) == 0
            ]

            if open_controls:
                qc.x(open_controls)

            if controls:
                qc.mcx(controls, x[target])
            else:
                qc.x(x[target])

            if open_controls:
                qc.x(open_controls)

    visited = [False] * L

    for start in range(L):
        if visited[start]:
            continue

        cycle = []
        value = start
        while not visited[value]:
            visited[value] = True
            cycle.append(value)
            value = (a * value) % L

        for value in cycle[1:]:
            swap_basis_states(cycle[0], value)

    return qc

