from qiskit import transpile


def solve(n: int, a: int, L: int) -> QuantumCircuit:
    x, y = QuantumRegister(n), QuantumRegister(n + 1)
    qc = QuantumCircuit(x, y)

    if a == 1:
        return qc

    size = 1 << n
    forward = [(a * value) % L if value < L else value
               for value in range(size)]
    inverse = [0] * size
    for value, image in enumerate(forward):
        inverse[image] = value

    def xor_function(source, destination, table):
        coefficients = table[:]
        for bit in range(n):
            bit_mask = 1 << bit
            for mask in range(size):
                if mask & bit_mask:
                    coefficients[mask] ^= coefficients[mask ^ bit_mask]

        for mask, coefficient in enumerate(coefficients):
            if coefficient == 0:
                continue

            controls = [source[i] for i in range(n) if mask & (1 << i)]
            targets = [
                destination[i]
                for i in range(n)
                if coefficient & (1 << i)
            ]
            pivot = targets[0]

            for target in targets[1:]:
                qc.cx(pivot, target)

            if not controls:
                qc.x(pivot)
            elif len(controls) == 1:
                qc.cx(controls[0], pivot)
            elif len(controls) == 2:
                qc.ccx(controls[0], controls[1], pivot)
            else:
                qc.mcx(controls, pivot)

            for target in targets[1:]:
                qc.cx(pivot, target)

    xor_function(x, y, forward)

    for bit in range(n):
        qc.swap(x[bit], y[bit])

    xor_function(x, y, inverse)

    qc = transpile(qc, basis_gates=["u", "cx"], optimization_level=1)
    return qc

