from qiskit import QuantumCircuit, QuantumRegister


def solve(n: int, a: int, L: int) -> QuantumCircuit:
    x, y = QuantumRegister(n), QuantumRegister(n + 1)
    qc = QuantumCircuit(x, y)

    if a == 1:
        return qc

    modulus = 1 << n
    accumulator = list(y[:n])
    flag = y[n]

    def controlled_x(controls, target):
        count = len(controls)
        if count == 0:
            qc.x(target)
        elif count == 1:
            qc.cx(controls[0], target)
        elif count == 2:
            qc.ccx(controls[0], controls[1], target)
        else:
            qubits = list(controls) + [target]
            angle = pi / (1 << count)

            qc.h(target)
            for pivot_index, pivot in enumerate(qubits):
                previous = 0
                for step in range(1 << pivot_index):
                    gray = step ^ (step >> 1)
                    if step:
                        changed = gray ^ previous
                        qc.cx(qubits[changed.bit_length() - 1], pivot)
                    qc.p(angle if step % 2 == 0 else -angle, pivot)
                    previous = gray

                if previous:
                    qc.cx(qubits[previous.bit_length() - 1], pivot)
            qc.h(target)

    def toggle_less_than(register, threshold, enable):
        if threshold <= 0:
            return
        if threshold >= modulus:
            qc.cx(enable, flag)
            return

        for bit in range(n - 1, -1, -1):
            if not ((threshold >> bit) & 1):
                continue

            open_controls = [register[bit]]
            open_controls.extend(
                register[j]
                for j in range(bit + 1, n)
                if not ((threshold >> j) & 1)
            )

            for qubit in open_controls:
                qc.x(qubit)

            controlled_x([enable] + register[bit:], flag)

            for qubit in reversed(open_controls):
                qc.x(qubit)

    def controlled_add(register, constant, enable):
        constant %= modulus
        for bit in range(n):
            if not ((constant >> bit) & 1):
                continue

            for target in range(n - 1, bit, -1):
                controlled_x(
                    [enable] + register[bit:target],
                    register[target],
                )
            qc.cx(enable, register[bit])

    def controlled_modular_add(register, constant, enable):
        constant %= L
        if constant == 0:
            return

        if L == modulus:
            controlled_add(register, constant, enable)
            return

        qc.cx(enable, flag)
        toggle_less_than(register, L - constant, enable)

        controlled_add(register, constant, enable)
        controlled_add(register, -L, flag)

        toggle_less_than(register, constant, enable)

    for bit in range(n):
        controlled_modular_add(
            accumulator, (a * (1 << bit)) % L, x[bit]
        )

    for bit in range(n):
        qc.cx(x[bit], accumulator[bit])
        qc.cx(accumulator[bit], x[bit])
        qc.cx(x[bit], accumulator[bit])

    inverse_a = pow(a, -1, L)
    for bit in range(n):
        controlled_modular_add(
            accumulator, (-inverse_a * (1 << bit)) % L, x[bit]
        )

    return qc

