def solve(n: int, a: int, L: int) -> QuantumCircuit:
    x, y = QuantumRegister(n), QuantumRegister(n + 1)
    qc = QuantumCircuit(x, y)

    size = 1 << n
    permutation = [
        (a * value) % L if value < L else value
        for value in range(size)
    ]
    operations = []

    def eliminate(control_mask, target):
        operations.append((control_mask, target))
        target_mask = 1 << target
        for index in range(size):
            if (permutation[index] & control_mask) == control_mask:
                permutation[index] ^= target_mask

    for desired in range(size):
        current = permutation[desired]

        for target in range(n):
            bit = 1 << target
            if (desired & bit) and not (current & bit):
                eliminate(current, target)
                current ^= bit

        for target in range(n):
            bit = 1 << target
            if (current & bit) and not (desired & bit):
                eliminate(desired, target)
                current ^= bit

    for control_mask, target_index in reversed(operations):
        controls = [
            x[bit] for bit in range(n)
            if control_mask & (1 << bit)
        ]
        target = x[target_index]
        count = len(controls)

        if count == 0:
            qc.x(target)
        elif count == 1:
            qc.cx(controls[0], target)
        elif count == 2:
            qc.ccx(controls[0], controls[1], target)
        else:
            qc.ccx(controls[0], controls[1], y[0])

            for index in range(2, count - 1):
                qc.ccx(y[index - 2], controls[index], y[index - 1])

            qc.ccx(y[count - 3], controls[-1], target)

            for index in reversed(range(2, count - 1)):
                qc.ccx(y[index - 2], controls[index], y[index - 1])

            qc.ccx(controls[0], controls[1], y[0])

    return qc

