    qc.h(x)

    coefficients = [pow(a, k, L) for k in range(1 << n)]
    for bit in range(n):
        for mask in range(1 << n):
            if mask & (1 << bit):
                coefficients[mask] ^= coefficients[mask ^ (1 << bit)]

    for mask, value in enumerate(coefficients):
        if value == 0:
            continue

        controls = [x[bit] for bit in range(n) if mask & (1 << bit)]
        for bit in range(m):
            if value & (1 << bit):
                if not controls:
                    qc.x(y[bit])
                elif len(controls) == 1:
                    qc.cx(controls[0], y[bit])
                else:
                    qc.mcx(controls, y[bit])

    return qc

