def solve(n: int, m: int, a: int, L: int) -> QuantumCircuit:
    x, y = QuantumRegister(n), QuantumRegister(2 * m + 1)
    qc = QuantumCircuit(x, y)

    qc.h(x)
    qc.x(y[0])

    def controlled_edge_swap(control, first, second):
        target_bit = (first ^ second).bit_length() - 1
        other_bits = [j for j in range(m) if j != target_bit]
        zero_controls = [y[j] for j in other_bits if not ((first >> j) & 1)]

        for qubit in zero_controls:
            qc.x(qubit)

        controls = [control] + [y[j] for j in other_bits]
        if len(controls) == 1:
            qc.cx(controls[0], y[target_bit])
        else:
            qc.mcx(controls, y[target_bit])

        for qubit in reversed(zero_controls):
            qc.x(qubit)

    def controlled_basis_swap(control, first, second):
        path = [first]
        current = first

        for bit in range(m):
            if ((first ^ second) >> bit) & 1:
                current ^= 1 << bit
                path.append(current)

        for j in range(len(path) - 1):
            controlled_edge_swap(control, path[j], path[j + 1])

        for j in range(len(path) - 3, -1, -1):
            controlled_edge_swap(control, path[j], path[j + 1])

    for exponent_bit in range(n):
        multiplier = pow(a, 1 << exponent_bit, L)
        if multiplier == 1:
            continue

        visited = [False] * L
        for start in range(L):
            if visited[start]:
                continue

            cycle = []
            current = start
            while not visited[current]:
                visited[current] = True
                cycle.append(current)
                current = (multiplier * current) % L

            for value in cycle[1:]:
                controlled_basis_swap(x[exponent_bit], cycle[0], value)

    return qc

