def solve(n: int, m: int, a: int, L: int) -> QuantumCircuit:
    x, y = QuantumRegister(n), QuantumRegister(2 * m + 1)
    qc = QuantumCircuit(x, y)

    qc.h(x)
    qc.h(y[:m])

    flag = y[m]
    controls = list(x)

    for k in range(1 << n):
        value = pow(a, k, L)
        zero_controls = [x[j] for j in range(n) if not (k >> j) & 1]

        for qubit in zero_controls:
            qc.x(qubit)

        if n == 1:
            qc.cx(x[0], flag)
        else:
            qc.mcx(controls, flag)

        for j in range(m):
            denominator = 1 << (m - j)
            residue = value % denominator
            if residue:
                qc.cp(2 * pi * residue / denominator, flag, y[j])

        if n == 1:
            qc.cx(x[0], flag)
        else:
            qc.mcx(controls, flag)

        for qubit in reversed(zero_controls):
            qc.x(qubit)

    for j in range(m // 2):
        qc.swap(y[j], y[m - 1 - j])

    for j in range(m):
        for lower in range(j):
            qc.cp(-pi / (1 << (j - lower)), y[lower], y[j])
        qc.h(y[j])

    return qc

