def solve(n: int) -> QuantumCircuit:
    qc = QuantumCircuit(n)

    def controlled_root_x(control: int, target: int, exponent: int) -> None:
        if exponent == 0:
            qc.cx(control, target)
        elif exponent == 1:
            qc.csx(control, target)
        else:
            theta = pi / (1 << exponent)
            qc.cu(theta, -pi / 2, pi / 2, theta / 2, control, target)

    if n <= 5:
        left = [
            (control, target, target - control)
            for target in range(n - 1, 1, -1)
            for control in range(target - 1, 0, -1)
        ]

        for gate in left:
            controlled_root_x(*gate)

        for target in range(1, n):
            controlled_root_x(0, target, target - 1)

        for gate in reversed(left):
            controlled_root_x(*gate)

        return qc

    depth = 4 * n - 10
    layers = [[] for _ in range(depth)]

    for control in range(1, n - 1):
        for target in range(control + 1, n):
            if control >= 2:
                time = 2 * n - 2 - control - target
            elif target < n - 1:
                time = 2 * n - 2 - 2 * target
            else:
                time = n - 1 + (n & 1)

            gate = (control, target, target - control)
            layers[time - 1].append(gate)
            layers[depth - time].append(gate)

    for target in range(1, n):
        time = 2 * n - 3 - target
        layers[time - 1].append((0, target, target - 1))

    for layer in layers:
        for gate in layer:
            controlled_root_x(*gate)

    return qc

