def solve(n: int, m_before: int, k_before: int,
          m_after: int, k_after: int) -> QuantumCircuit:
    qc = QuantumCircuit(n + 1)
    modulus = 1 << n
    m_qubit = n
    k_qubits = list(range(n))

    sign = -1 if m_before else 1
    constant = (k_before + m_before + sign * k_after) % modulus
    controlled_constant = (-2 * sign * k_after) % modulus

    if m_before:
        for qubit in k_qubits:
            qc.x(qubit)

    qft = QuantumCircuit(n)
    for target in range(n - 1, -1, -1):
        qft.h(target)
        for control in range(target - 1, -1, -1):
            qft.cp(pi / (1 << (target - control)), control, target)
    for qubit in range(n // 2):
        qft.swap(qubit, n - 1 - qubit)

    qc.compose(qft, qubits=k_qubits, inplace=True)

    for qubit in k_qubits:
        phase = (constant << qubit) % modulus
        if phase:
            qc.p(2 * pi * phase / modulus, qubit)

        controlled_phase = (controlled_constant << qubit) % modulus
        if controlled_phase:
            qc.cp(2 * pi * controlled_phase / modulus, m_qubit, qubit)

    qc.compose(qft.inverse(), qubits=k_qubits, inplace=True)

    if m_before ^ m_after:
        qc.x(m_qubit)

    return qc

