def solve(n: int, m_before: int, k_before: int,
          m_after: int, k_after: int) -> QuantumCircuit:
    qc = QuantumCircuit(n + 1)
    modulus = 1 << n
    m_qubit = 0
    k_qubits = list(range(1, n + 1))

    def add_constant(value: int, control=None):
        value %= modulus
        for bit in range(n):
            if not ((value >> bit) & 1):
                continue

            for target in range(n - 1, bit, -1):
                controls = k_qubits[bit:target]
                if control is not None:
                    controls = [control] + controls

                if len(controls) == 1:
                    qc.cx(controls[0], k_qubits[target])
                else:
                    qc.mcx(controls, k_qubits[target])

            if control is None:
                qc.x(k_qubits[bit])
            else:
                qc.cx(control, k_qubits[bit])

    if m_before:
        for qubit in k_qubits:
            qc.x(qubit)
        add_constant(k_before + 1 - k_after)
        add_constant(2 * k_after, control=m_qubit)
    else:
        add_constant(k_before + k_after)
        add_constant(-2 * k_after, control=m_qubit)

    if m_before ^ m_after:
        qc.x(m_qubit)

    return qc

from math import pi
from qiskit import QuantumCircuit


def solve(n: int, m_before: int, k_before: int,
          m_after: int, k_after: int) -> QuantumCircuit:
    qc = QuantumCircuit(n + 1)
    m_qubit = 0
    k_qubits = list(range(1, n + 1))
    modulus = 1 << n

    def shift(value: int) -> None:
        value %= modulus
        if value == 0:
            return

        trailing_zeros = (value & -value).bit_length() - 1
        register = k_qubits[trailing_zeros:]
        value >>= trailing_zeros
        width = len(register)

        if width == 1:
            qc.x(register[0])
            return

        for target in range(width - 1, -1, -1):
            qc.h(register[target])
            for control in range(target - 1, -1, -1):
                qc.cp(
                    pi / (1 << (target - control)),
                    register[control],
                    register[target],
                )

        for target, qubit in enumerate(register):
            residue = value % (1 << (target + 1))
            qc.p(pi * residue / (1 << target), qubit)

        for target in range(width):
            for control in range(target):
                qc.cp(
                    -pi / (1 << (target - control)),
                    register[control],
                    register[target],
                )
            qc.h(register[target])

    if k_after == 0:
        if m_before:
            for qubit in k_qubits:
                qc.x(qubit)

        shift(k_before + m_before)

        if m_before ^ m_after:
            qc.x(m_qubit)

        return qc

    for qubit in reversed(k_qubits):
        qc.cx(m_qubit, qubit)

    shift(k_after)

    if m_before:
        qc.x(m_qubit)

    for qubit in k_qubits:
        qc.cx(m_qubit, qubit)

    shift(k_before + m_before)

    if m_after:
        qc.x(m_qubit)

    return qc
